/* @jsx h */
import type { Register } from "claude-code";
import { WhoClient } from "./client";
import { Leaderboard, clean, compact, windowSize, type Period } from "./pane";
const ID = "who-leaderboard";
export const register: Register = (on, options) => {
  let client: WhoClient | undefined, app: Leaderboard | undefined;
  on("session.start", async ($, e, next) => {
    try {
      client = new WhoClient(
        {
          get: (key) => $.store.get(key),
          set: (key, value) => $.store.set(key, value),
          remove: (key) => $.store.delete(key),
          keys: () => $.store.keys(),
          fetch: (url, init) => $.http.fetch(url, init),
          run: (argv, init) => $.process.run(argv, init),
          status: (text) => $.ui.status(text),
          now: () => $.clock.now(),
          after: (ms, fn) => $.clock.after(ms, fn),
          root: $.plugin.root,
        },
        String(options.relayUrl ?? ""),
        String(options.displayName ?? "me"),
      );
      await client.init(await $.session.id());
      app = new Leaderboard(client, {
        invalidate: () => $.ui.invalidate("ui.render"),
        open: (focus) =>
          $.ui.open({
            id: ID,
            title: "Claude Who",
            rows: 26,
            ...(focus ? { focus: true as const } : {}),
          }),
        close: () => $.ui.close({ id: ID }),
        defer: (fn) => {
          $.clock.after(0, fn);
        },
        save: (open) => $.store.set("ui:open", open),
      });
      const active = client,
        pane = app;
      await $.command.register({
        name: "who",
        description: "Live friends leaderboard",
        argumentHint:
          "[today|week|month|create|join|members|messages|close|help]",
        immediate: true,
      });
      $.clock.every(30000, () => {
        void active.heartbeat();
        if (pane.opened && !pane.loading) void pane.refresh();
      });
      $.clock.every(10000, () => {
        void pane.pollMessages();
      });
      $.clock.every(300000, () => {
        void active
          .sync()
          .then(() => {
            if (pane.opened) void pane.refresh();
          })
          .catch(() => $.ui.status("who: offline"));
      });
      const reopen = await $.store.get("ui:open").catch(() => false);
      $.clock.after(0, () => {
        void active.heartbeat();
        void active.sync().catch(() => $.ui.status("who: offline"));
        if (reopen === true)
          void pane.show("today", undefined, false).catch(() => {});
      });
    } catch {
      $.ui.status("who: setup failed");
    }
    return next(e);
  });
  on("turn.start", async ($, e, next) => {
    if (!("agentId" in e)) await client?.turn("working");
    return next(e);
  });
  on("turn.complete", async ($, e, next) => {
    await client?.turn("idle", e.agentId);
    if (e.agentId === undefined && app?.opened) void app.refresh();
    return next(e);
  });
  on("command.run", { command: "who" }, async ($, e) => {
    if (!client || !app) return { text: "Plugin is starting; try again." };
    const parts = e.args.trim().split(/\s+/).filter(Boolean),
      command = parts[0];
    if (!command || ["today", "week", "month"].includes(command)) {
      if (parts.length > 2)
        return { text: "Usage: /who [today|week|month] [group]" };
      await app.show((command ?? "today") as Period, parts[1]);
      return {};
    }
    if (command === "close") {
      await app.close();
      return {};
    }
    if (command === "refresh") {
      await app.show();
      return {};
    }
    if (command === "create" && parts.length === 1) {
      await app.show();
      app.edit("create");
      return {};
    }
    if (command === "join" && parts.length === 1) {
      await app.show();
      app.edit("join");
      return {};
    }
    if (command === "messages") {
      if (parts.length > 2) return { text: "Usage: /who messages [group]" };
      await app.show(app.period, parts[1]);
      app.edit("messages");
      return {};
    }
    if (command === "members") {
      await app.show(app.period, parts[1]);
      app.edit("members");
      return {};
    }
    const text = await client.command(
      command === "text" ? parts.slice(1).join(" ") : e.args,
    );
    if (["create", "join", "leave", "default"].includes(command))
      app.group = "";
    if (app.opened) void app.refresh();
    return {
      text:
        command === "help"
          ? `/who opens the live leaderboard. Today / Week / Month buttons change periods. Esc returns to your prompt and keeps the board open. /who close closes it. /who text today prints a text board.\n${text}`
          : text,
    };
  });
  on("ui.close", { id: ID }, async ($, e, next) => {
    const result = await next(e);
    if (!result || !("deny" in result) || !result.deny) app?.markClosed();
    return result;
  });
  on("ui.render", { component: "Pane" }, ($, e, next) => {
    if (e.requestId !== ID || !app || e.surface === "mobile") return next(e);
    const { Box, Text, Button, Select, Input } = $.ui.resolve(e),
      pane = app;
    const columns = e.props.bodyColumns;
    if (columns < 34)
      return (
        <Text dimColor>
          Widen the pane to 34 columns to see the leaderboard.
        </Text>
      );
    const rows =
      pane.fresh || e.props.scroll.bodyRows === 0
        ? 26
        : e.props.scroll.bodyRows;
    pane.fresh = false;
    const defer = (fn: () => Promise<unknown>) =>
      pane.host.defer(() => {
        void fn().catch(() => {});
      });
    const title = (
      <Text bold color="cyan" wrap="truncate-end">
        CLAUDE WHO / {clean(pane.data?.groupName || "Your circle")}
      </Text>
    );
    if (pane.form === "messages" || pane.form === "compose") {
      const message = pane.currentMessage;
      const friends = pane.recipients;
      if (pane.form === "compose" && !pane.reply && friends.length === 0)
        return (
          <Box flexDirection="column" width={columns}>
            {title}
            <Text bold>New private message</Text>
            <Text>
              {pane.loading
                ? "Loading group members…"
                : pane.error
                  ? "Could not load recipients. Try refreshing."
                  : !pane.data
                    ? "Loading group members…"
                    : "No other members in this group. Invite a friend first."}
            </Text>
            <Box flexDirection="row" columnGap={1}>
              <Button
                key="refresh-recipients"
                label="Refresh members"
                onPress={() => {
                  void pane.refresh();
                }}
              />
              <Button
                key="compose-back"
                label="Back"
                onPress={() => pane.edit("messages")}
              />
            </Box>
            {pane.error ? <Text color="yellow">{pane.error}</Text> : null}
          </Box>
        );
      const text = Array.from(
        (message?.text ?? "").replace(
          /[\x00-\x1f\x7f-\x9f\u202a-\u202e\u2066-\u2069]/g,
          " ",
        ),
      );
      const width = Math.max(16, columns - 4),
        pageSize = width * Math.max(1, Math.min(5, rows - 14));
      const pages = Math.max(1, Math.ceil(text.length / pageSize));
      pane.messagePage = Math.min(pane.messagePage, pages - 1);
      const shown = text.slice(
        pane.messagePage * pageSize,
        (pane.messagePage + 1) * pageSize,
      );
      const lines = Array.from(
        { length: Math.ceil(shown.length / width) },
        (_, i) => shown.slice(i * width, (i + 1) * width).join(""),
      );
      return (
        <Box flexDirection="column" width={columns}>
          {title}
          <Text bold>
            {pane.form === "compose"
              ? pane.reply
                ? `Reply to ${clean(pane.reply.senderName)}`
                : "New private message"
              : `Messages · ${pane.messages.length} pending`}
          </Text>
          <Text dimColor>
            Private to recipient · expires in 24h · no history
          </Text>
          {pane.form === "compose" ? (
            <Box flexDirection="column">
              {pane.reply ? (
                <Text dimColor wrap="truncate-end">
                  {clean(pane.reply.text)}
                </Text>
              ) : (
                <Select
                  key="message-recipient"
                  label="To"
                  value={pane.recipientId || "choose-recipient"}
                  options={[
                    ...(!pane.recipientId
                      ? [
                          {
                            label: "Choose a friend",
                            value: "choose-recipient",
                          },
                        ]
                      : []),
                    ...friends.map((m) => ({ label: m.name, value: m.id })),
                  ]}
                  onSelect={(v) =>
                    pane.chooseRecipient(v === "choose-recipient" ? "" : v)
                  }
                />
              )}
              <Input
                key="message-draft"
                label="Message"
                placeholder="Say hello…"
                value={pane.draft}
                autoFocus
                submitLabel="send"
                onInput={(v) => {
                  if (pane.actionBusy) return;
                  pane.draft = v.slice(0, 1000);
                }}
                onSubmit={(v) => {
                  if (pane.actionBusy) return;
                  pane.draft = v.slice(0, 1000);
                  pane.send();
                }}
              />
              <Box flexDirection="row" columnGap={1}>
                <Button
                  key="send-message"
                  label={pane.actionBusy ? "Sending…" : "Send"}
                  onPress={() => pane.send()}
                />
                <Button
                  key="cancel-message"
                  label="Back"
                  onPress={() => {
                    if (!pane.actionBusy) pane.edit("messages");
                  }}
                />
              </Box>
            </Box>
          ) : (
            <Box flexDirection="column">
              {message ? (
                <Box flexDirection="column">
                  <Select
                    key="inbox-message"
                    label="From"
                    value={`${message.senderId}:${message.id}`}
                    options={pane.messages.map((m) => ({
                      label: `${clean(m.senderName)} · ${new Date(m.createdAt).toISOString().slice(11, 16)} UTC`,
                      value: `${m.senderId}:${m.id}`,
                    }))}
                    onSelect={(v) => {
                      pane.messageKey = v;
                      pane.messagePage = 0;
                      pane.host.invalidate();
                    }}
                  />
                  {lines.map((line, i) => (
                    <Text key={`message-line-${i}`}>{line}</Text>
                  ))}
                  {pages > 1 ? (
                    <Box flexDirection="row" columnGap={1}>
                      <Button
                        key="message-prev-page"
                        label="←"
                        onPress={() => {
                          pane.messagePage = Math.max(0, pane.messagePage - 1);
                          pane.host.invalidate();
                        }}
                      />
                      <Text dimColor>
                        {pane.messagePage + 1}/{pages}
                      </Text>
                      <Button
                        key="message-next-page"
                        label="→"
                        onPress={() => {
                          pane.messagePage = Math.min(
                            pages - 1,
                            pane.messagePage + 1,
                          );
                          pane.host.invalidate();
                        }}
                      />
                    </Box>
                  ) : null}
                  <Box flexDirection="row" columnGap={1}>
                    <Button
                      key="reply-message"
                      label="Reply"
                      onPress={() => pane.compose(message)}
                    />
                    <Button
                      key="dismiss-message"
                      label={pane.actionBusy ? "Working…" : "Dismiss"}
                      onPress={() => pane.dismiss()}
                    />
                  </Box>
                  <Text dimColor>
                    Replying or dismissing clears this message.
                  </Text>
                </Box>
              ) : (
                <Text dimColor>
                  {pane.inboxLoading
                    ? "Checking messages…"
                    : "No pending messages."}
                </Text>
              )}
              <Box flexDirection="row" columnGap={1}>
                <Button
                  key="new-message"
                  label="New message"
                  onPress={() => pane.compose()}
                />
                <Button
                  key="refresh-messages"
                  label="Refresh"
                  onPress={() => {
                    void pane.refreshMessages();
                  }}
                />
                <Button
                  key="messages-back"
                  label="Back"
                  onPress={() => pane.edit("board")}
                />
              </Box>
            </Box>
          )}
          <Text color={pane.error ? "yellow" : undefined}>
            {pane.error || pane.notice}
          </Text>
        </Box>
      );
    }
    if (pane.form === "members") {
      const data = pane.data;
      const people = data?.members ?? [];
      const removable = people.filter((m) => !m.isCreator);
      if (!removable.some((m) => m.name === pane.selectedMember))
        pane.selectedMember = removable[0]?.name ?? "";
      return (
        <Box flexDirection="column" width={columns}>
          {title}
          <Text bold>Members & invitations</Text>
          <Text dimColor wrap="truncate-end">
            {people
              .map((m) => `${clean(m.name)}${m.isCreator ? " (creator)" : ""}`)
              .join(" · ")}
          </Text>
          {data?.isCreator ? (
            <Box flexDirection="column">
              <Box flexDirection="row" columnGap={1}>
                <Button
                  key="copy-invite"
                  label={pane.actionBusy ? "Working…" : "Copy invite"}
                  onPress={() => pane.copyInvite()}
                />
                <Button
                  key="rotate-invite"
                  label="New invite"
                  onPress={() => {
                    pane.confirmation = "rotate";
                    pane.host.invalidate();
                  }}
                />
              </Box>
              {removable.length > 0 ? (
                <Box flexDirection="column">
                  <Select
                    key="remove-member"
                    label="Member"
                    value={pane.selectedMember}
                    options={removable.map((m) => ({
                      label: m.name,
                      value: m.name,
                    }))}
                    onSelect={(v) => {
                      pane.selectedMember = v;
                      pane.confirmation = null;
                      pane.host.invalidate();
                    }}
                  />
                  <Button
                    key="remove"
                    label="Remove member"
                    onPress={() => {
                      pane.confirmation = "remove";
                      pane.host.invalidate();
                    }}
                  />
                </Box>
              ) : (
                <Text dimColor>No other members yet.</Text>
              )}
              {pane.confirmation ? (
                <Box flexDirection="column">
                  {pane.confirmation === "generate-copy" ? (
                    <Text>No current invite saved on this device.</Text>
                  ) : null}
                  <Text color="yellow">
                    {pane.confirmation === "remove"
                      ? `Remove ${clean(pane.selectedMember)} and delete their data?`
                      : "Replace invite? The previous invitation will stop working."}
                  </Text>
                  <Text dimColor>
                    {pane.confirmation === "remove"
                      ? "Removing a member also replaces the invite."
                      : "Existing members stay connected."}
                  </Text>
                  <Box flexDirection="row" columnGap={1}>
                    <Button
                      key="confirm"
                      label={
                        pane.confirmation === "generate-copy"
                          ? "Generate and copy"
                          : "Confirm"
                      }
                      onPress={() => pane.confirm()}
                    />
                    <Button
                      key="cancel"
                      label="Cancel"
                      onPress={() => {
                        pane.confirmation = null;
                        pane.host.invalidate();
                      }}
                    />
                  </Box>
                </Box>
              ) : (
                <Text dimColor>
                  Only the creator can remove members or manage invites.
                </Text>
              )}
            </Box>
          ) : (
            <Text dimColor>
              The group creator manages invitations and members.
            </Text>
          )}
          <Button
            key="back-board"
            label="Back"
            onPress={() => pane.edit("board")}
          />
          <Text color={pane.error ? "yellow" : undefined} wrap="truncate-end">
            {pane.error || pane.notice}
          </Text>
        </Box>
      );
    }
    if (pane.form !== "board")
      return (
        <Box flexDirection="column" width={columns}>
          {title}
          <Text dimColor>
            {pane.form === "create"
              ? "Start a group with your friends"
              : "Join your friends"}
          </Text>
          <Text dimColor>
            Shares 30 days of token metadata. No conversation text.
          </Text>
          {pane.form === "create" ? (
            <Input
              key="group-name"
              label="Group"
              placeholder="close-friends"
              value={pane.groupInput}
              autoFocus
              onInput={(v) => {
                pane.groupInput = v;
              }}
              onSubmit={(v) => {
                pane.groupInput = v;
                pane.submit();
              }}
            />
          ) : (
            <Box flexDirection="column">
              <Input
                key="invite-code"
                label="Code"
                placeholder="WHO-XXXX-XXXX"
                value={pane.codeInput}
                autoFocus
                onInput={(v) => {
                  pane.codeInput = v;
                }}
                onSubmit={(v) => {
                  pane.codeInput = v;
                }}
              />
              <Input
                key="your-name"
                label="Your name"
                placeholder="sam"
                value={pane.nameInput}
                onInput={(v) => {
                  pane.nameInput = v;
                }}
                onSubmit={(v) => {
                  pane.nameInput = v;
                  pane.submit();
                }}
              />
            </Box>
          )}
          <Box flexDirection="row" columnGap={1}>
            <Button
              key="submit"
              label={
                pane.loading
                  ? "Connecting…"
                  : pane.form === "create"
                    ? "Create group"
                    : "Join group"
              }
              onPress={() => pane.submit()}
            />
            <Button
              key="back"
              label="Back"
              dimColor
              onPress={() => pane.edit("board")}
            />
          </Box>
          <Text color="yellow" wrap="truncate-end">
            {pane.notice ||
              pane.error ||
              "Create uses your configured display name."}
          </Text>
        </Box>
      );
    const data = pane.data;
    if (!data && pane.loading)
      return (
        <Box flexDirection="column">
          {title}
          <Text dimColor>Loading the leaderboard…</Text>
        </Box>
      );
    if (!data?.groups.length)
      return (
        <Box flexDirection="column" width={columns}>
          {title}
          <Text bold>Your friends. Their flow. A little competition.</Text>
          <Text dimColor>
            See who is working and climb the live leaderboard.
          </Text>
          <Text> </Text>
          <Box flexDirection="row" columnGap={1}>
            <Button
              key="create"
              label="Create a group"
              onPress={() => pane.edit("create")}
            />
            <Button
              key="join"
              label="Join a group"
              onPress={() => pane.edit("join")}
            />
          </Box>
          <Text dimColor>
            Shares token metadata only — never your conversations.
          </Text>
          <Text color="yellow" wrap="truncate-end">
            {pane.error ||
              (pane.loading ? "Loading your groups…" : pane.notice)}
          </Text>
        </Box>
      );
    const pageSize = windowSize(rows, data.unreadMessages > 0),
      pages = Math.max(1, Math.ceil(data.rows.length / pageSize));
    pane.page = Math.min(pane.page, pages - 1);
    const visible = data.rows.slice(
        pane.page * pageSize,
        (pane.page + 1) * pageSize,
      ),
      top = Math.max(1, ...data.rows.map((r) => r.tokens));
    const me = data.rows.find((r) => r.name === data.me),
      working = data.rows.filter((r) => r.state === "working").length;
    return (
      <Box flexDirection="column" width={columns}>
        {title}
        {data.unreadMessages > 0 ? (
          <Box flexDirection="row" columnGap={1}>
            <Text
              bold
              color="yellow"
            >{`● ${data.unreadMessages} ${data.unreadMessages === 1 ? "message" : "messages"}`}</Text>
            <Button
              key="notification-inbox"
              label="Open inbox"
              onPress={() => {
                if (!pane.actionBusy) pane.edit("messages");
              }}
            />
          </Box>
        ) : null}
        <Box flexDirection="row" columnGap={1}>
          {(["today", "week", "month"] as Period[]).map((period) => (
            <Button
              key={period}
              label={period[0]!.toUpperCase() + period.slice(1)}
              dimColor={pane.period !== period}
              onPress={() => pane.change(period)}
            />
          ))}
          <Button
            key="refresh"
            label={pane.loading ? "…" : "↻"}
            onPress={() => defer(() => pane.refresh())}
          />
        </Box>
        <Box flexDirection="row" columnGap={1}>
          {data.isCreator && (
            <Button
              key="copy-invite-board"
              label={pane.actionBusy ? "Working…" : "Copy invite"}
              onPress={() => pane.copyInvite()}
            />
          )}
          <Button
            key="members"
            label="Members"
            onPress={() => pane.edit("members")}
          />
          <Button
            key="messages"
            label={`Messages${data.unreadMessages ? ` (${data.unreadMessages})` : ""}`}
            onPress={() => {
              if (!pane.actionBusy) pane.edit("messages");
            }}
          />
        </Box>
        <Select
          key="groups"
          label="Group"
          value={data.groupId}
          options={data.groups.map((g) => ({ value: g.id, label: g.name }))}
          onSelect={(value) => pane.change(pane.period, value)}
        />
        <Text bold wrap="truncate-end">
          {working} working · {data.rows.length} friends · You #
          {me?.rank ?? "—"} / {compact(me?.tokens ?? 0)}
        </Text>
        <Text dimColor wrap="truncate-end">
          WORK TOKENS · input + output
        </Text>
        {visible.map((row) => {
          const barWidth = Math.max(8, Math.min(24, columns - 24)),
            filled = Math.round((row.tokens / top) * barWidth);
          return (
            <Box key={row.name} flexDirection="column">
              <Text
                bold={row.name === data.me}
                color={row.name === data.me ? "cyan" : undefined}
                wrap="truncate-end"
              >
                {row.rank <= 3
                  ? ["🥇", "🥈", "🥉"][row.rank - 1]
                  : `#${row.rank}`}{" "}
                {clean(row.name)}
                {row.name === data.me ? " (you)" : ""} · {compact(row.tokens)}
              </Text>
              <Text
                color={row.state === "working" ? "green" : undefined}
                dimColor={row.state === "offline"}
                wrap="truncate-end"
              >
                {"█".repeat(filled)}
                {"░".repeat(barWidth - filled)}{" "}
                {row.state === "working"
                  ? "●"
                  : row.state === "idle"
                    ? "◐"
                    : "○"}{" "}
                {clean(row.state)}
              </Text>
              <Text dimColor wrap="truncate-end">
                {row.gap ? `${compact(row.gap)} behind · ` : ""}synced{" "}
                {row.lastSyncAt
                  ? clean(row.lastSyncAt.slice(11, 16)) + " UTC"
                  : "never"}
              </Text>
            </Box>
          );
        })}
        <Box flexDirection="row" columnGap={1}>
          <Button
            key="prev"
            label="←"
            dimColor={pane.page === 0}
            onPress={() => {
              pane.page = Math.max(0, pane.page - 1);
              pane.host.invalidate();
            }}
          />
          <Text dimColor>
            {pane.page + 1}/{pages}
          </Text>
          <Button
            key="next"
            label="→"
            dimColor={pane.page === pages - 1}
            onPress={() => {
              pane.page = Math.min(pages - 1, pane.page + 1);
              pane.host.invalidate();
            }}
          />
          <Button
            key="add"
            label="+ Group"
            dimColor
            onPress={() => pane.edit("join")}
          />
          <Button
            key="close"
            label="Close"
            dimColor
            onPress={() => defer(() => pane.close())}
          />
        </Box>
        <Text
          color={pane.error ? "yellow" : undefined}
          dimColor={!pane.error}
          wrap="truncate-end"
        >
          {pane.error
            ? pane.error
            : pane.notice ||
              `Live · board 30s / messages 10s · Esc returns to code`}
        </Text>
      </Box>
    );
  });
};

