export type DirectMessage = {
  id: string;
  senderId: string;
  senderName: string;
  text: string;
  createdAt: number;
  expiresAt: number;
};
export class InviteUnavailableError extends Error {}
export type Host = {
  get: (key: string) => Promise<unknown>;
