        )
          this.error = clean(e instanceof Error ? e.message : String(e));
      } finally {
        this.badgeLoading = false;
        this.host.invalidate();
      }
    } else if (this.form === "messages" || this.form === "compose") {
      await this.refreshMessages();
    }
  }
  async refreshMessages() {
    if (!this.opened || this.inboxLoading || !this.group) return;
    const group = this.group,
      generation = ++this.inboxGeneration;
    this.inboxLoading = true;
    try {
      const messages = await this.client.inbox(group);
      if (
        generation !== this.inboxGeneration ||
        group !== this.group ||
        !this.opened
      )
        return;
      this.messages = messages;
      if (this.reply && this.reply.expiresAt <= Date.now())
        this.reply = undefined;
      if (this.data) this.data.unreadMessages = messages.length;
    } catch (e) {
      if (generation === this.inboxGeneration)
        this.error = clean(e instanceof Error ? e.message : String(e));
    } finally {
      if (generation === this.inboxGeneration) {
        this.inboxLoading = false;
        this.messages = this.messages.filter((m) => m.expiresAt > Date.now());
        if (this.reply && this.reply.expiresAt <= Date.now())
          this.reply = undefined;
        this.host.invalidate();
      }
    }
  }
  compose(message?: DirectMessage) {
    if (this.actionBusy) return;
    this.reply = message;
    this.recipientNeedsChoice = false;
    this.recipientId = message?.senderId ?? this.recipients[0]?.id ?? "";
    this.draft = "";
    this.pendingSend = undefined;
    this.edit("compose");
  }
  send() {
    if (this.actionBusy) return;
    const text = this.draft.trim(),
      recipientId = this.recipientId,
      group = this.group,
      replyTo = this.reply?.id;
    if (!this.reply && !this.recipients.some((m) => m.id === recipientId)) {
      this.error =
        "No recipient selected. Refresh members or invite a friend first.";
      this.host.invalidate();
      return;
    }
    if (!recipientId || !text || text.length > 1000) {
      this.error = "Choose a friend and write 1–1000 characters.";
      this.host.invalidate();
      return;
    }
    if (
      !this.pendingSend ||
      this.pendingSend.text !== text ||
      this.pendingSend.recipientId !== recipientId ||
      this.pendingSend.group !== group ||
      this.pendingSend.replyTo !== replyTo
    )
      this.pendingSend = {
        id: crypto.randomUUID(),
        text,
        recipientId,
        group,
        replyTo,
      };
    const pending = this.pendingSend;
    this.action(async () => {
      await this.client.sendMessage(
        recipientId,
        text,
        pending.id,
        group,
        replyTo,
      );
      if (this.group !== group || !this.opened) return;
      this.draft = "";
      this.pendingSend = undefined;
      this.reply = undefined;
      this.inboxGeneration++;
      this.inboxLoading = false;
      this.edit("messages");
      this.notice = "Message sent.";
      await this.refreshMessages();
    });
  }
  dismiss() {
    const message = this.currentMessage,
      group = this.group;
    if (!message) return;
    this.action(async () => {
      await this.client.dismissMessage(message, group);
      if (this.group !== group) return;
      this.inboxGeneration++;
      this.inboxLoading = false;
      this.messages = this.messages.filter(
        (m) => m.id !== message.id || m.senderId !== message.senderId,
      );
      this.messageKey = "";
      this.messagePage = 0;
      if (this.data) this.data.unreadMessages = this.messages.length;
      this.notice = "Message dismissed.";
    });
  }
  constructor(
    readonly client: Pick<
      WhoClient,
      | "snapshot"
      | "command"
      | "copyInvitation"
      | "removeMember"
      | "rotateInvite"
      | "inbox"
      | "messageCount"
      | "sendMessage"
      | "dismissMessage"
    >,
    readonly host: PaneHost,
  ) {}
  async show(period: Period = this.period, group?: string, focus = true) {
    this.opened = true;
    this.period = period;
    if (group !== undefined && group !== this.group) {
      this.clearMessages();
      this.data = undefined;
      this.group = group;
    }
    this.page = 0;
    this.fresh = true;
    await this.host.open(focus);
    await this.host.save(true).catch(() => {});
    void this.refresh();
  }
  async close() {
    await this.host.close();
    this.markClosed();
  }
  markClosed() {
    this.opened = false;
    this.clearMessages();
    this.generation++;
    void this.host.save(false).catch(() => {});
  }
  change(period: Period, group = this.group) {
    this.period = period;
    this.group = group;
    this.clearMessages();
    this.page = 0;
    this.data = undefined;
    this.error = "";
    this.generation++;
    void this.refresh();
  }
  async refresh() {
    const generation = ++this.generation;
    this.loading = true;
    this.host.invalidate();
    try {
      const data = await this.client.snapshot(
        this.period,
        this.group || undefined,
      );
      if (generation !== this.generation) return;
      this.data = data;
      this.group = data.groupId;
      this.error = "";
      this.reconcileRecipient();
      if (this.form === "messages" || this.form === "compose")
        void this.refreshMessages();
    } catch (e) {
      if (generation === this.generation)
        this.error = clean(e instanceof Error ? e.message : String(e));
    } finally {
      if (generation === this.generation) {
        this.loading = false;
        this.host.invalidate();
      }
    }
  }
  edit(form: View) {
    if (form !== "messages" && form !== "compose") this.clearMessages();
    this.form = form;
    if (form === "messages") void this.refreshMessages();
    this.confirmation = null;
    this.notice = "";
    this.fresh = true;
    this.host.defer(() => {
      void this.host.open(true).catch(() => {});
    });
    this.host.invalidate();
  }
  action(work: () => Promise<void>) {
    if (this.actionBusy) return;
    this.actionBusy = true;
    this.notice = "";
    this.error = "";
    this.host.invalidate();
    this.host.defer(() => {
      void work()
        .catch((e) => {
          this.error = clean(e instanceof Error ? e.message : String(e));
        })
        .finally(() => {
          this.actionBusy = false;
          this.host.invalidate();
        });
    });
  }
  copyInvite() {
    const group = this.group;
    this.action(async () => {
      try {
        await this.client.copyInvitation(group);
        this.notice = "Invitation copied to clipboard.";
      } catch (e) {
        if (!(e instanceof InviteUnavailableError) || this.group !== group)
          throw e;
        this.edit("members");
        this.confirmation = "generate-copy";
      }
    });
  }
  confirm() {
    const group = this.group,
      target = this.selectedMember,
      action = this.confirmation;
    this.confirmation = null;
    this.action(async () => {
      if (action === "remove") {
        this.notice = await this.client.removeMember(target, group);
        this.selectedMember = "";
        await this.refresh();
      } else if (action === "generate-copy") {
        await this.client.rotateInvite(group);
        await this.client.copyInvitation(group);
        this.notice = "New invitation copied to clipboard.";
      } else if (action === "rotate") {
        await this.client.rotateInvite(group);
        this.notice = "New invite created. Copy invitation to share it.";
      }
    });
  }
  submit() {
    if (this.loading) return;
    const args =
      this.form === "create"
        ? `create ${this.groupInput}`
        : `join ${this.codeInput} ${this.nameInput}`;
    this.loading = true;
    this.host.invalidate();
    this.host.defer(() => {
      void this.createOrJoin(args);
    });
  }
  private async createOrJoin(args: string) {
    try {
      const result = await this.client.command(args);
      this.notice = clean(result.split("\n")[0] ?? result);
      const invite = result.match(/WHO-[A-Z2-7]{4}(?:-[A-Z2-7]{4}){1,7}/)?.[0];
      if (invite)
        this.notice = `Invite friends: /who join ${invite} THEIR_NAME`;
      if (result.startsWith("Created ") || result.startsWith("Joined ")) {
        this.form = "board";
        this.group = "";
        this.data = undefined;
        await this.refresh();
      }
    } catch (e) {
      this.error = clean(String(e));
    } finally {
      this.loading = false;
      this.host.invalidate();
    }
  }
}

